"""Nội dung ôn bảo vệ. Mã và số dòng được bộ dựng đọc từ website hiện hành."""
QUESTIONS = []

def q(code, title, ask, answer, logic, refs, demo, follow, trap, excerpt=None):
    QUESTIONS.append(dict(id=code,title=title,ask=ask,answer=answer,logic=logic,refs=refs,demo=demo,follow=follow,trap=trap,excerpt=excerpt))

M='js/mo-hinh.js'; U='js/hien-thi.js'; S='js/luu-tru.js'; E='js/su-kien.js'
D='js/du-lieu.js'; H='js/trang/trang-chu.js'; P='js/trang/san-pham.js'
G='js/trang/gio-hang.js'; O='js/trang/dat-hang.js'; A='js/trang/tai-khoan.js'
def r(file, anchor, label): return [file,anchor,label]

q('A01','Chủ đề và luồng mua hàng','Website của em bán gì, phục vụ ai và khách mua như thế nào?',
'Em xây dựng PC-Astral Market bán laptop, PC để bàn, màn hình và phụ kiện cho người học, làm việc và chơi game. Khách xem sản phẩm, tìm hoặc lọc, thêm giỏ rồi nhập thông tin nhận hàng để đặt đơn mô phỏng. Dự án chạy ở trình duyệt với dữ liệu tĩnh, không thu tiền hay gửi đơn đến cửa hàng thật.',
'Khách chọn sản phẩm → Cart giữ lựa chọn → form kiểm tra thông tin → lưu bản chụp đơn và hiển thị xác nhận. Khách không bắt buộc đăng nhập mới được đặt đơn trong phiên bản hiện tại.',
[r(D,'"categories": [','Bốn danh mục'),r(O,'function xuLyDatHang(','Xử lý đặt hàng')],
'Mở trang chủ, chỉ bốn danh mục rồi đi từ chi tiết đến giỏ và trang đặt hàng. Chỉ dòng COD mô phỏng trên xác nhận.',
'Có trừ tồn kho thật không? Không; quantity là tồn kho minh họa để giới hạn một giỏ, chưa quản lý kho nhiều khách.',
'Không gọi đây là hệ thống thương mại điện tử có backend, thanh toán thật hoặc giao vận.')
q('A02','Đối chiếu Y1 đến Y3','Em chỉ ra các yêu cầu của Assignment đã nằm ở đâu?',
'Y1 nằm ở các chức năng chạy được: nhóm sản phẩm, danh mục, hiệu ứng, slider, form, giỏ và countdown. Y2 là cách đặt HTML ở gốc, JavaScript trong js và CSS trong css. Y3 là báo cáo có phân tích, hình vẽ và thông tin công nghệ, API, công cụ; bộ câu hỏi này chỉ là tài liệu ôn thêm.',
'Đối chiếu yêu cầu với màn hình và mã xử lý, không chỉ với ảnh chụp. Website dùng JavaScript thuần; DOM, LocalStorage và timer là API trình duyệt, không phải thư viện được cài.',
[r(H,'function khoiTaoTrangChu(','Nhóm sản phẩm, slider, countdown'),r('index.html','<script','Thẻ nạp JS')],
'Mở docs/doi-chieu-de-bai.md cùng website, lần lượt chỉ slider, giỏ, validation và ba chức năng tự đề xuất.',
'Dùng thư viện gì? Website không nạp thư viện JavaScript bên ngoài; công cụ tạo Word/kiểm thử chỉ phục vụ phát triển.',
'Không lấy kết quả của công cụ phát triển làm thư viện chạy trong website.')
q('A03','Ba chức năng tự đề xuất','Ba yêu cầu nhóm tự đề xuất là gì và vì sao cần?',
'Em chọn tìm kiếm, lọc và sắp xếp. Tìm kiếm giúp khách đã biết tên hoặc hãng tìm nhanh; lọc giúp thu hẹp theo loại hàng và ngân sách; sắp xếp giúp so sánh giá hoặc tên. Cả ba cùng áp dụng trên danh sách, có số kết quả và trạng thái không tìm thấy.',
'Đọc từ khóa cùng bộ lọc → giữ sản phẩm thỏa tất cả điều kiện → sắp xếp mảng kết quả → render. Trạng thái được phản ánh lên URL để tải lại không mất lựa chọn.',
[r(U,'function locSanPham(','Tìm, lọc, sắp xếp'),r(P,'function capNhatURL(','Ghi trạng thái URL')],
'Tìm ASUS, chọn Laptop, chọn khoảng giá và giá giảm dần; F5 rồi kiểm tra các lựa chọn vẫn còn.',
'Muốn thêm tìm theo mã thì sửa đâu? Mở locSanPham và bổ sung id vào chuỗi tìm kiếm; xem bài C06.',
'Không kể ba nhóm mới/hot/khuyến mãi thay cho ba chức năng tự đề xuất.')
q('A04','Chia file và khởi tạo','Vì sao chia nhiều file và trang bắt đầu chạy từ đâu?',
'Em tách dữ liệu, mô hình, lưu trữ, hiển thị và sự kiện để sửa đúng nơi. HTML nạp script bằng defer theo thứ tự và file sự kiện khởi tạo ứng dụng. Hàm khởi tạo chờ dữ liệu, tạo Product và Cart, dựng phần chung rồi gọi logic riêng theo data-page của trang.',
'JSON dự phòng → cấu hình/nạp dữ liệu → storage → models → hiển thị → đăng ký hàm trang → sự kiện khởi tạo. Các file trao đổi qua window.PCAstral.',
[r('index.html','<script','Thứ tự script'),r(E,'async function khoiTaoWebsite(','Điểm khởi tạo')],
'Mở phần khai báo script trong index.html, sau đó tìm khoiTaoWebsite và dòng tạo Cart. Chỉ nơi lấy hàm từ ungDung.pages.',
'Vì sao không dùng async ở thẻ script? Nó không bảo đảm thứ tự phụ thuộc như các script defer hiện tại.',
'defer không có nghĩa mọi fetch đã hoàn tất; ứng dụng vẫn phải await dữ liệu.')
q('A05','Nguồn dữ liệu sản phẩm','Dữ liệu sản phẩm lưu ở đâu, muốn thêm sản phẩm thì sửa chỗ nào?',
'Nguồn chính là js/products.json, hiện có 24 sản phẩm thuộc 4 danh mục. Em thêm một object với ID riêng và đủ bảy trường bắt buộc, đặt ảnh trong img rồi dùng đường dẫn tương đối. js/du-lieu.js đọc và kiểm tra JSON trước khi tạo Product.',
'Sửa JSON → kiểm tra cú pháp và dữ liệu → HTTP nạp lại khi F5. Khi bàn giao file mở trực tiếp, phải sinh lại san-pham-du-phong.js từ JSON; không sửa tay hai bộ dữ liệu.',
[r('js/products.json','"id": "p01"','Mẫu sản phẩm'),r(D,'function kiemTraSanPham(','Kiểm tra dữ liệu'),r(D,'async function napDuLieuSanPham(','Nạp JSON')],
'Chỉ bảy trường id, name, price, imgUrl, description, category, quantity. Luyện thêm sản phẩm theo C01 trên bản sao.',
'Chỉ sửa JSON rồi mở file:// có thấy ngay không? Không; phải đồng bộ bản JSON nhúng trước.',
'Không viết tay thêm một thẻ HTML và coi đó là thêm dữ liệu sản phẩm.')
q('A06','JSON và object JavaScript','JSON có giống hệt object trong JavaScript không?',
'JSON là định dạng văn bản để lưu hoặc trao đổi dữ liệu. Object JavaScript là giá trị đang tồn tại khi chương trình chạy và có thể gắn phương thức. JSON yêu cầu tên trường và chuỗi dùng dấu nháy kép, không chứa function hay comment như mã JavaScript.',
'Đọc văn bản JSON → phân tích thành mảng object → kiểm tra trường → tạo đối tượng Product. Chỉ sau bước tạo Product mới gọi được các phương thức như layGia.',
[r(D,'danhSachJSON = JSON.parse(','Phân tích JSON nhúng'),r(E,'const sanPham = new ungDung.models.Product(','Tạo Product')],
'Mở JSON và mo-hinh.js cạnh nhau: dữ liệu chỉ có trường, class có phương thức. Không cố gọi layGia trực tiếp trên object vừa JSON.parse.',
'JSON có lưu giá là số được không? Có; giá phải là số, chỉ định dạng thành chuỗi tiền lúc hiển thị.',
'Không nhầm đuôi .js với định dạng JSON thuần hoặc cho rằng JSON tự giữ class.')
q('A07','Vì sao dùng mảng object','Sao em không dùng các mảng tên, giá và ảnh riêng?',
'Mỗi object gom các thuộc tính của cùng một sản phẩm nên dễ đọc và sửa. Mảng chứa nhiều sản phẩm để duyệt và render. Nếu tách nhiều mảng theo thuộc tính, việc xóa hoặc đổi thứ tự một mảng có thể làm lệch tên, giá và ảnh.',
'Tìm sản phẩm bằng ID ổn định → lấy tên, giá, ảnh từ cùng đối tượng. Vị trí trong mảng có thể đổi khi lọc hoặc sắp xếp; ID vẫn là khóa dùng trong giỏ.',
[r('js/products.json','"id": "p01"','Một sản phẩm'),r(M,'timSanPham(maSanPham) {','Tra sản phẩm theo ID')],
'Chỉ một object p01, sau đó tìm productId trong Cart. Giải thích vì sao sắp xếp màn hình không làm giỏ đổi sản phẩm.',
'Có dùng chỉ số mảng làm mã giỏ không? Không, chỉ số không ổn định khi dữ liệu thay đổi.',
'Không nói mảng object là cơ sở dữ liệu SQL hoặc tự có quan hệ ràng buộc như SQL.')
q('A08','Trách nhiệm Product và Cart','Hai class của em có thuộc tính, phương thức gì và dùng để làm gì?',
'Product chứa thông tin một sản phẩm và các phương thức kiểm tra giá, tồn kho, tên danh mục. Cart giữ danh sách dòng giỏ và thao tác thêm, sửa, xóa, tính tổng. Hai class xử lý dữ liệu; phần hiển thị DOM nằm ở file giao diện hoặc file trang.',
'Product nhận dữ liệu JSON. Cart nhận danh sách Product, các dòng đã lưu và hàm được gọi khi giỏ đổi; mỗi dòng chỉ giữ productId và quantity.',
[r(M,'class Product {','Class Product'),r(M,'class Cart {','Class Cart'),r(M,'tinhTongGio(thoiDiem) {','Tính tổng')],
'Chỉ ít nhất năm phương thức Product: dangGiamGia, layGia, layGiaHienThi, conHang, coTheMua; rồi chỉ themSanPham, xoaSanPham, tinhTongGio của Cart.',
'quantity ở Product và dòng giỏ có giống nhau? Không: một bên là tồn kho minh họa, một bên là số lượng khách chọn.',
'Không thêm sửa HTML vào mô hình chỉ để làm class trông có nhiều phương thức.')
q('A09','Render danh sách','Chứng minh sản phẩm được render bằng JS chứ không viết tay từng thẻ?',
'HTML chỉ chứa vùng danh sách, còn dữ liệu sản phẩm được truyền vào hàm hiển thị. Hàm duyệt danh sách và tạo nội dung từng thẻ từ thuộc tính sản phẩm. Do đó số thẻ phụ thuộc dữ liệu sau lọc, không phải số thẻ em viết sẵn trong HTML.',
'Danh sách Product → taoTheSanPham cho từng phần tử → ghép vào vùng lưới. Danh sách rỗng được hiển thị bằng thông báo có hướng dẫn mua hoặc tìm lại.',
[r(U,'function taoTheSanPham(','Nội dung thẻ'),r(U,'function hienThiLuoiSanPham(','Dựng lưới'),r(P,'function hienThiDanhSachSanPham(','Trang danh sách')],
'Mở products.html và chỉ products-grid; dùng từ khóa không tồn tại để thấy trạng thái rỗng, xóa lọc để có lại 24 sản phẩm.',
'Vì sao nội dung khách nhập dùng textContent? Để hiển thị thành chữ, không diễn giải như HTML.',
'Không lấy ảnh chụp màn hình làm bằng chứng duy nhất cho render dữ liệu.')
q('A10','Event delegation','Vì sao gắn listener ở thẻ cha mà không gắn từng nút?',
'Sự kiện click từ nút có thể nổi lên phần tử cha. Em đặt một listener ở cha, rồi xác định nút được bấm bằng closest và data-*. Khi thêm hoặc render lại dòng sản phẩm, các nút mới vẫn dùng listener đó, không cần gắn lại từng nút.',
'Click ở nút hoặc con của nút → sự kiện đến cha → tìm nút theo data-* phù hợp → gọi phương thức giỏ. Chỉ xử lý nhánh có nút khớp.',
[r(E,'function xuLyBamNutChung(','Click chung'),r(G,'khung.addEventListener(\'click\'','Listener cha giỏ')],
'Mở khung giỏ, chỉ một listener click và thử tăng/xóa ở hai sản phẩm khác nhau. Cả hai được xử lý theo ID riêng.',
'Mọi sự kiện đều delegation giống click được không? Không nên khẳng định vậy; cần xét việc sự kiện có nổi lên hay không.',
'Không gắn listener trong vòng render mỗi lần cập nhật rồi làm một click chạy nhiều lần.')
q('A11','Target và closest','event.target là gì, khác currentTarget và closest thế nào?',
'target là phần tử thực tế phát sinh sự kiện, có thể là chữ hoặc thẻ con trong nút. currentTarget là phần tử đang có listener xử lý. closest tìm từ phần tử hiện tại lên tổ tiên để lấy phần tử khớp selector, nên em vẫn tìm được nút khi người dùng bấm vào phần con.',
'Nhận sự kiện → closest tìm nút → nếu không có thì return → đọc dataset của nút. Dữ liệu trong dataset là chuỗi nên phải đổi sang số khi cần tính toán.',
[r(E,'function xuLyThemGio(','Tìm nút thêm giỏ'),r(G,'function xuLyBamNutGio(','Tìm nút tăng giảm')],
'Chỉ dòng Number(nutDoiSoLuong.dataset.step), giải thích nếu cộng chuỗi thì có thể cho kết quả nối chữ.',
'Bấm ngoài nút thêm giỏ thì sao? closest trả null; hàm dừng và không thêm sản phẩm.',
'Không đồng nhất target với thẻ cha đang nghe sự kiện.')
q('A12','Thêm sản phẩm trùng','Bấm Thêm giỏ hai lần cùng sản phẩm thì mã chạy ra sao?',
'Cart tìm dòng đã có bằng ID. Nếu có, em cộng số lượng mới vào dòng cũ; nếu chưa có thì thêm một dòng. Trước khi sửa, tổng số lượng dự kiến phải hợp lệ và không vượt tồn kho.',
'ID + số lượng → tìm Product và dòng cũ → kiểm tra tổng cũ cộng mới → tăng dòng hoặc push → gọi lưu giỏ và phát sự kiện cập nhật.',
[r(M,'themSanPham(maSanPham, soLuong) {','Gộp sản phẩm trùng'),r(E,'function luuGio(','Lưu và thông báo giỏ đổi')],
'Thêm p01 hai lần rồi mở giỏ: chỉ một dòng, quantity bằng 2, thành tiền bằng hai lần đơn giá; F5 vẫn đúng.',
'Đã có 4, kho 5, thêm 2 thì sao? Bị từ chối, không ép thao tác thêm thành 1 hoặc tạo dòng khác.',
'Không chỉ tăng badge; phải tăng dữ liệu trong Cart và lưu được.',(M,'      const tongSoLuong = soLuongCu + soLuong;',10))
q('A13','Tính tổng bằng vòng for','Tổng tiền tính ở đâu, tại sao dùng reduce?',
'Trong bản hiện tại em không dùng reduce mà dùng vòng for trong tinhTongGio. Mỗi vòng lấy đơn giá hiện hành, nhân số lượng rồi cộng vào tổng khởi tạo bằng 0. Cách viết từng bước phù hợp mức JavaScript cơ bản và dễ kiểm tra phép tính.',
'Cart.items → tra Product → layGia ở cùng thời điểm → thành tiền = đơn giá × số lượng → cộng tổng tiền và tổng số lượng. Phí vận chuyển demo là 0.',
[r(M,'tinhTongGio(thoiDiem) {','Nguồn tính tổng'),r(U,'function dinhDangTien(','Định dạng khi hiển thị')],
'Chọn hai sản phẩm, tự nhân đơn giá với số lượng rồi đối chiếu tổng. Chỉ sự khác nhau giữa số loại hàng và tổng số lượng.',
'Sao không cộng chuỗi có dấu chấm và đ? Chuỗi đó chỉ để hiển thị; tính toán dùng số nguyên VNĐ.',
'Không trả lời máy móc theo slide rằng dự án đang dùng reduce.',(M,'        const donGia = sanPham.layGia(thoiDiem);',3,-1))
q('A14','Số lượng không hợp lệ','Nếu giảm về 0, nhập số âm, số lẻ hoặc vượt tồn kho thì sao?',
'Dự án quy định số lượng là số nguyên từ 1 đến tồn kho. Nhập sai bị chặn và giao diện trở lại số lượng hợp lệ trước đó. Muốn bỏ sản phẩm thì dùng nút Xóa; nút giảm cũng bị khóa khi số lượng đang là 1.',
'Đổi chuỗi input thành Number → Product.coTheMua kiểm tra → Cart chỉ gán khi hợp lệ → nếu sai báo lỗi và hiển thị lại dữ liệu cũ.',
[r(M,'coTheMua(soLuong) {','Điều kiện số lượng'),r(M,'doiSoLuong(maSanPham, soLuong) {','Chỉ sửa khi hợp lệ'),r(G,'function xuLyDoiSoLuong(','Khôi phục giao diện')],
'Từ số lượng 2, lần lượt nhập 0, -1, 1.5 và số vượt kho. Sau mỗi lần, kiểm tra vẫn là 2 và tổng không đổi.',
'min/max trong HTML đã đủ chưa? Chưa; dữ liệu còn được kiểm tra trong JavaScript trước khi sửa Cart.',
'Không nói giảm về 0 sẽ tự xóa vì mã hiện tại chặn thao tác này.')
q('A15','Giữ giỏ khi F5','F5 tạo trang mới thì vì sao giỏ vẫn còn?',
'Biến trong bộ nhớ được tạo lại khi tải trang, nhưng LocalStorage vẫn giữ dữ liệu đã lưu. Khi khởi tạo, em đọc các dòng giỏ, kiểm tra rồi tạo Cart mới. Giao diện và badge được dựng từ Cart đó, không dựa vào con số còn sót trong HTML.',
'Thao tác đổi giỏ → JSON.stringify → setItem. Khi F5: getItem → JSON.parse → kiemTraGio → new Cart → render. Trường hợp ghi bị chặn phải báo rõ là chưa bảo đảm lưu.',
[r(E,'function luuGio(','Ghi giỏ'),r(E,'const gioDaLuu =','Đọc lại giỏ khi khởi tạo'),r(S,'function docJSON(','Đọc storage')],
'Thêm hai sản phẩm, đổi số lượng, F5 và chuyển trang; đối chiếu Cart, LocalStorage và màn hình.',
'Tắt Live Server có xóa không? Không, dự án không có cơ chế tự xóa khi server dừng.',
'Không đánh đồng F5 với nút Kết thúc buổi demo.',(E,'    const gioDaLuu =',3))
q('A16','Chuyển đổi JSON khi lưu','Vì sao cần JSON.stringify và JSON.parse?',
'LocalStorage lưu giá trị dạng chuỗi. stringify chuyển mảng hoặc object thành chuỗi JSON, còn parse khôi phục giá trị để chương trình xử lý. Em bọc việc đọc và phân tích trong try/catch vì dữ liệu có thể bị sửa hỏng hoặc trình duyệt chặn truy cập.',
'Ghi: object → chuỗi → storage. Đọc: chuỗi hoặc null → parse nếu có → trả dữ liệu; lỗi thì thông báo và dùng giá trị dự phòng được truyền vào.',
[r(S,'function docJSON(','Đọc và xử lý lỗi'),r(S,'function luuJSON(','Ghi chuỗi JSON')],
'Xem giỏ trong Application → Local Storage; chuỗi JSON có các dòng productId và quantity. Không thử dữ liệu hỏng trên phiên chứa thông tin cần giữ.',
'Người dùng xóa storage thì trang có lỗi không? Khi không còn khóa, hàm đọc trả dự phòng; giỏ khởi tạo rỗng.',
'JSON.parse không xác nhận dữ liệu đúng nghiệp vụ; vẫn cần kiểm tra trường và số lượng.',(S,'  function luuJSON(',7))
q('A17','Username và mật khẩu lưu ở đâu','Đăng ký xong thì username và password lưu ở đâu? LocalStorage mất khi F5 đúng không?',
'Dạ không, F5 không tự xóa LocalStorage. Tài khoản nằm ở khóa pc-astral.users.v1, gồm username, salt và passwordHash; em không lưu mật khẩu nguyên văn. Mật khẩu nhập vào được băm trước khi ghi, và tài khoản vẫn dùng để đăng nhập sau khi tải lại.',
'Kiểm tra form và tên trùng → chuẩn hóa username → tạo salt ngẫu nhiên → chờ băm → kiểm tra demo chưa reset → ghi danh sách tài khoản. Mật khẩu không được lưu thành bản nháp.',
[r(S,"const USERS_KEY =",'Khóa tài khoản'),r(S,'async function bamMatKhau(','Tạo mã băm'),r(S,'danhSachTaiKhoan.push({ username:','Ba trường được lưu'),r(S,'function luuJSON(','Ghi LocalStorage')],
'Đăng ký tài khoản thử onthi01, dùng mật khẩu chỉ dành cho demo. Mở Application xem ba trường, F5, rồi đăng nhập bằng đúng mật khẩu vừa nhập.',
'Có đọc ngược hash ra mật khẩu không? Không; đăng nhập tạo hash từ dữ liệu nhập rồi so sánh. Đây vẫn là mô phỏng phía trình duyệt.',
'Không nói lưu password dạng chữ thường, mã hóa có thể giải mã, hoặc F5 tự xóa tài khoản.',(S,'    danhSachTaiKhoan.push({ username:',5))
q('A18','So sánh mật khẩu khi đăng nhập','Không lưu mật khẩu gốc thì kiểm tra đăng nhập bằng cách nào?',
'Em tìm tài khoản theo username đã chuẩn hóa. Sau đó băm mật khẩu vừa nhập với đúng salt của tài khoản và so sánh với passwordHash đã lưu. Nếu khớp và lưu được trạng thái đăng nhập thì báo thành công; sai thông tin thì báo lỗi chung.',
'Username → tìm tài khoản → băm mật khẩu nhập → kiểm tra reset/tài khoản chưa thay đổi → so hash → lưu AUTH_KEY chỉ chứa username → cập nhật giao diện.',
[r(S,'async function dangNhap(','Luồng đăng nhập'),r(S,'if (maBamVuaNhap !== taiKhoan.passwordHash)','So mã băm'),r(A,'async function xuLyDangNhap(','Sự kiện form')],
'Thử sai mật khẩu rồi đúng mật khẩu; F5 để kiểm tra trạng thái. Đăng xuất rồi đăng nhập lại chứng minh tài khoản chưa bị xóa.',
'Đăng ký xong có tự đăng nhập không? Không; giao diện điền sẵn username, chuyển focus sang mật khẩu để người dùng đăng nhập.',
'Không so sánh mật khẩu vừa nhập trực tiếp với chuỗi hash.')
q('A19','Đăng xuất và kết thúc demo','Đăng xuất và Kết thúc buổi demo khác nhau thế nào?',
'Đăng xuất chỉ xóa khóa trạng thái đăng nhập nên tài khoản và giỏ vẫn còn. Kết thúc demo có xác nhận và xóa riêng các khóa ứng dụng như giỏ, đơn, tài khoản, đăng nhập và bản nháp. Dấu reset được cập nhật để thao tác đang chờ hoặc tab khác biết buổi demo đã kết thúc.',
'Đăng xuất → xoaDuLieu(AUTH_KEY). Reset → ghi mốc RESET_KEY → xóa từng khóa nghiệp vụ → chuyển về trang chủ; không gọi localStorage.clear().',
[r(S,'function dangXuat(','Chỉ xóa đăng nhập'),r(S,'function ketThucDemo(','Xóa dữ liệu ứng dụng'),r(E,'function xuLyLuuTruThayDoi(','Tab khác nhận reset')],
'Đăng xuất rồi đăng nhập lại. Chỉ ở cuối buổi thử, bấm Kết thúc demo và kiểm tra không đăng nhập lại được bằng tài khoản cũ.',
'Vì sao còn khóa reset? Đây là dấu điều phối thao tác, không phải tài khoản hay giỏ còn sót.',
'Không dùng clear() xóa mọi dữ liệu của cùng origin; không nói tắt server tự kết thúc demo.')
q('A20','Thứ tự đặt hàng','Khi bấm đặt hàng, tại sao không xóa giỏ ngay?',
'Em kiểm tra form, giỏ và giá trước khi tạo đơn. Đơn phải được lưu thành công rồi mới xóa bản nháp và dọn giỏ để tránh mất lựa chọn khi storage lỗi. Nếu giỏ hoặc giá thay đổi, lần bấm đó chỉ yêu cầu xem lại; chưa tạo đơn.',
'Chặn gửi lặp → validate → lấy tổng → kiểm tra rỗng/thay đổi → tạo snapshot → lưu ORDER_KEY → ghi URL mã đơn → xóa nháp → thử dọn giỏ → hiển thị xác nhận.',
[r(O,'function xuLyDatHang(','Thứ tự đặt hàng'),r(O,'function taoDonHang(','Bản chụp đơn'),r(O,'function thuDonGio(','Dọn giỏ đúng đơn')],
'Gửi form trống để thấy lỗi, điền hợp lệ rồi đặt; kiểm tra mã đơn, tổng, giỏ và F5 xác nhận. Toàn bộ là đơn mô phỏng.',
'Đơn lưu được nhưng giỏ chưa xóa thì sao? Hiển thị đơn đã lưu và nút thử dọn lại, không tạo đơn mới.',
'Không coi mọi lỗi ở cuối luồng là đặt hàng thất bại rồi tạo thêm đơn.')

q('B01','let const và thuộc tính object','Dùng const rồi tại sao em vẫn sửa được quantity?',
'const không cho gán lại chính biến sang giá trị khác. Với object, nó không tự đóng băng các thuộc tính bên trong nên vẫn sửa được thuộc tính. Em dùng let cho biến cần gán lại, const cho tham chiếu không cần thay; việc sửa thuộc tính vẫn phải đi qua logic giỏ.',
'const dong giữ tham chiếu đến dòng giỏ; dong.quantity đổi thuộc tính của dòng đó. Nó khác với việc gán dong sang một object mới.',
[r(M,'doiSoLuong(maSanPham, soLuong) {','Biến dòng và thuộc tính')],
'Mở doiSoLuong, chỉ const dong và phép gán dong.quantity. Giải thích hai dòng không mâu thuẫn.',
'const có làm mảng bất biến không? Không, vẫn có push/splice; dự án chủ động kiểm soát nơi sửa dữ liệu.',
'Không trả lời const nghĩa là mọi dữ liệu bên trong tuyệt đối không đổi.')
q('B02','Tham số return và phạm vi biến','Hàm nhận gì, trả gì và biến trong hàm dùng ở đâu?',
'Tham số là giá trị đầu vào giúp cùng một hàm xử lý nhiều trường hợp. return trả kết quả và kết thúc lần gọi hàm đó; return sớm giúp chặn dữ liệu sai. Biến khai báo trong khối hoặc hàm chỉ dùng được trong phạm vi tương ứng, tránh trùng tên giữa các phần.',
'Ví dụ coTheMua nhận số lượng, trả boolean. Bên gọi dựa vào true/false để quyết định cập nhật, không mặc định gọi hàm là thao tác đã thành công.',
[r(M,'coTheMua(soLuong) {','Đầu vào và kết quả'),r(G,'function xuLyDoiSoLuong(','Bên gọi kiểm tra kết quả')],
'Với kho 5, giải thích đầu ra khi truyền 2, 0 và 6. Chỉ nhánh return false trước phép gán.',
'Hàm không return thì nhận được gì? Giá trị undefined; vì vậy phải hiểu hợp đồng của từng hàm.',
'Không nhầm return trong một hàm với việc dừng toàn bộ website.')
q('B03','constructor this và new','new Product làm gì, this là đối tượng nào?',
'new tạo một đối tượng theo class và chạy constructor với dữ liệu được truyền vào. Trong constructor và các phương thức khi gọi qua đối tượng, this chỉ đối tượng đang được xử lý. Nhờ vậy mỗi sản phẩm giữ thông tin riêng nhưng dùng cùng các phương thức của class.',
'Một object JSON → constructor gán các thuộc tính → Product có dữ liệu riêng và phương thức chung. Product.quantity là tồn kho của sản phẩm đó.',
[r(M,'class Product {','Constructor sản phẩm'),r(E,'const sanPham = new ungDung.models.Product(','Gọi new Product')],
'Chỉ hai sản phẩm có giá khác nhau và cùng gọi layGia. Giải thích this.price lấy giá của sản phẩm đang gọi.',
'Có đổi tên constructor sang tiếng Việt không? Không; constructor là tên đặc biệt của class JavaScript.',
'Không gọi constructor là hàm render giao diện.')
q('B04','Khôi phục object và class','JSON.parse xong có gọi được layGia ngay không?',
'Không, dữ liệu vừa parse chỉ là object thông thường, không tự có phương thức Product. Ứng dụng tạo lại Product từ từng object JSON trước khi sử dụng. Tương tự, storage chỉ giữ các dòng giỏ, khi mở trang phải tạo Cart mới.',
'Parse mảng → kiểm tra dữ liệu → vòng for new Product → new Cart với dòng đã lưu. Không stringify toàn bộ đối tượng ứng dụng để mong lưu được hành vi của class.',
[r(E,'async function khoiTaoWebsite(','Tái tạo class'),r(M,'class Cart {','Constructor giỏ')],
'Mở khoiTaoWebsite và chỉ cả new Product lẫn new Cart. Phân biệt dữ liệu giữ lâu với phương thức được nạp lại từ JS.',
'Vì sao không lưu tên/giá trong dòng giỏ? Giỏ tra dữ liệu hiện tại từ Product; riêng đơn đã đặt có snapshot để giữ giá lúc đặt.',
'Không nói JSON chứa cả function và tự phục hồi prototype.')
q('B05','Object dùng chung PCAstral','Vì sao cần window.PCAstral, có làm mã quá phức tạp không?',
'Em dùng một object chung để các script thường trao đổi dữ liệu và hàm. Nó gom các nhóm data, models, storage, utils và ui thay vì tạo nhiều tên toàn cục dễ trùng. Mỗi file vẫn dùng hàm có tên và phạm vi biến riêng để đọc được theo từng nhiệm vụ.',
'File khai báo khả năng vào PCAstral → các file sau lấy đúng nhóm cần dùng → file sự kiện khởi tạo. Namespace không tự thực thi mọi chức năng; vẫn phải gọi đúng thứ tự.',
[r(D,'window.PCAstral =','Tạo object chung'),r(M,'window.PCAstral.models =','Công bố class'),r(E,'async function khoiTaoWebsite(','Kết nối các phần')],
'Trong Console gõ window.PCAstral, chỉ models và cart. Không sửa giá trị thật trong lúc bảo vệ chỉ để khám phá.',
'Có phải framework không? Không, đây là object JavaScript do dự án tự đặt tên.',
'Không bỏ namespace chỉ để ngắn hơn khi chưa kiểm tra xung đột biến.')
q('B06','defer và dữ liệu bất đồng bộ','Script defer rồi vì sao vẫn phải await dữ liệu?',
'defer giúp script chạy sau khi HTML được phân tích và theo thứ tự trong tài liệu. Việc đọc JSON bằng fetch vẫn bất đồng bộ nên script chạy không có nghĩa dữ liệu đã về. Em chờ ungDung.ready rồi mới tạo các đối tượng và render.',
'HTML có vùng DOM → script khai báo các phần → Promise nạp dữ liệu → await hoàn tất → dựng giao diện. Nếu dữ liệu lỗi, hiển thị thông báo thay vì tiếp tục với mảng không hợp lệ.',
[r('index.html','<script','Nạp defer'),r(D,'async function napDuLieuSanPham(','Đọc dữ liệu'),r(E,'const danhSachJSON = await ungDung.ready;','Chờ trước khi tạo đối tượng')],
'Chỉ dòng await đứng trước vòng new Product. Có thể xem Network để thấy products.json là tệp tĩnh trong cùng dự án.',
'fetch này có chứng minh website có backend không? Không, nó chỉ đọc một tệp tĩnh qua HTTP.',
'Không dùng setTimeout cố định để đoán dữ liệu đã tải xong.')
q('B07','Tìm kiếm không dấu','Tìm MÀN HÌNH bằng man hinh hoạt động thế nào?',
'Em chuẩn hóa cả từ khóa và nội dung tìm bằng cùng hàm boDau. Hàm tách dấu Unicode, bỏ dấu, đổi đ thành d, đưa về chữ thường và bỏ khoảng trắng đầu cuối. Sau đó includes kiểm tra chuỗi có chứa từ khóa.',
'Từ khóa → boDau; tên cộng thương hiệu → boDau → includes. Đây là tìm chuỗi con, chưa phải gợi ý thông minh hay tìm gần đúng khi gõ sai.',
[r(U,'function boDau(','Chuẩn hóa chữ'),r(U,'const chuoiTimKiem =','Tên và thương hiệu để tìm')],
'Thử “MÀN HÌNH”, “man hinh”, “  ASUS  ” và từ khóa vô nghĩa. So số kết quả và thông báo rỗng.',
'Muốn thêm tìm kiếm thì sửa file nào? Dự án đã có; sửa logic ở hien-thi.js và kết nối ô nhập ở trang san-pham.js.',
'Không chỉ chuẩn hóa một phía rồi kết luận tìm không dấu đã đầy đủ.',(U,'    let chuoi = String(giaTri);',6))
q('B08','Phép lọc AND','Vì sao chọn nhiều bộ lọc lại ít kết quả hơn?',
'Các điều kiện được kết hợp theo AND: sản phẩm phải thỏa tất cả điều kiện đang chọn. Trong vòng for, gặp điều kiện sai thì continue để bỏ qua sản phẩm đó. Chỉ sản phẩm đi qua đủ kiểm tra mới được push vào kết quả.',
'Kiểm tra từ khóa, danh mục, thương hiệu, nhóm và giá. Khoảng giá lấy cận dưới, không lấy cận trên nên mốc 15 triệu thuộc nhóm 15 đến dưới 30 triệu.',
[r(U,'function locSanPham(','Các nhánh continue'),r(U,'const cacKhoangGia =','Cận giá')],
'Chọn Laptop + ASUS rồi thêm khoảng giá; giải thích một sản phẩm bị loại ở điều kiện nào. Thử nút xóa bộ lọc.',
'Không có kết quả có phải lỗi JS không? Không; nếu dữ liệu không thỏa điều kiện, đó là trạng thái hợp lệ.',
'Không nói các bộ lọc đang dùng OR hoặc bao gồm cả hai cận giá.')
q('B09','Sắp xếp không sửa mảng gốc','sort thay đổi mảng, sao dữ liệu gốc vẫn giữ thứ tự?',
'Đúng là sort sắp xếp trực tiếp mảng được gọi. Hàm lọc tạo mảng ketQua riêng rồi sort mảng này, nên thứ tự mảng products gốc không đổi. Các phần tử vẫn tham chiếu Product; việc đổi thuộc tính sản phẩm là chuyện khác với đổi thứ tự mảng.',
'Duyệt dữ liệu gốc → push phần tử thỏa vào mảng mới → chọn hàm so sánh → sort kết quả → trả về. Mặc định không gọi sort.',
[r(U,'const ketQua = [];','Mảng kết quả mới'),r(U,'function soSanhGiaTang(','Hàm so sánh'),r(U,"if (boLoc.sort === 'price-asc')",'Chọn kiểu sắp xếp')],
'Đổi tăng dần, giảm dần rồi về mặc định. Kiểm tra thứ tự mặc định vẫn theo dữ liệu ban đầu.',
'Trả số âm nghĩa gì? Trong hàm so sánh, phần tử trước được xếp trước phần tử sau.',
'Không nói ketQua là bản sao sâu của mọi Product.')
q('B10','Bộ lọc giữ sau F5','Tại sao F5 vẫn giữ tìm kiếm và bộ lọc?',
'Trang danh sách ghi các lựa chọn vào query string của URL. Khi mở hoặc tải lại, nó đọc URL, kiểm tra giá trị được phép và điền vào form trước khi render. Cách này không cần một khóa LocalStorage riêng cho bộ lọc.',
'Form → trạng thái → URLSearchParams → history.replaceState. Chiều ngược: URL → giá trị hợp lệ hoặc mặc định → form → danh sách.',
[r(P,'function docBoLocTuURL(','Đọc và kiểm tra URL'),r(P,'function capNhatURL(','Ghi URL'),r(P,'function khoiPhucBoLoc(','Khôi phục lựa chọn')],
'Chọn danh mục và giá, quan sát URL rồi F5. Đổi category trên URL thành mã không tồn tại để thấy về mặc định.',
'replaceState có tải trang mới không? Không, nó đổi mục lịch sử hiện tại; mã vẫn chủ động render.',
'Không trả lời mọi dữ liệu sau F5 đều lấy từ LocalStorage.')
q('B11','Slider chuyển vòng','Từ banner cuối bấm tiếp, hoặc banner đầu bấm trước thì sao?',
'Slider giữ một biến vị trí bắt đầu từ 0. Hàm chuyển cộng bước rồi kiểm tra giới hạn: nhỏ hơn 0 thì về cuối, lớn hơn hoặc bằng độ dài thì về đầu. Hàm hiển thị dùng vị trí mới để đổi ảnh, chữ, liên kết và trạng thái chấm.',
'Click next/prev → chuyenBanner với 1 hoặc -1 → điều chỉnh vị trí → hienThiBanner. Click chấm đặt vị trí trực tiếp theo data-slide.',
[r(H,'function chuyenBanner(','Chuyển vòng'),r(H,'function hienThiBanner(','Cập nhật nội dung'),r(H,'function xuLyChonBanner(','Điều khiển chấm')],
'Bấm cuối → tiếp và đầu → trước; thử chấm số 2, kiểm tra ảnh và liên kết cùng đổi.',
'Thêm banner thứ tư chỉ push dữ liệu đủ chưa? Chấm và vòng lặp theo length, nhưng bộ đếm hiện đang ghi cố định /03; bài C04 sửa cả chỗ đó.',
'Không bỏ qua chữ bộ đếm cố định khi mở rộng số banner.')
q('B12','Timer và tạm dừng slider','Vì sao slider có lúc không tự chuyển sau 6 giây?',
'Timer gọi hàm tự chuyển mỗi 6 giây, nhưng hàm còn kiểm tra trạng thái người dùng. Nếu đang rê chuột, có focus bên trong banner, tab ẩn hoặc đã bấm tạm dừng thì nó return. Nhờ vậy nội dung không đổi trong lúc người dùng đang đọc hoặc thao tác.',
'Timer → kiểm tra bốn điều kiện dừng → nếu được phép mới chuyển 1 bước. Nút tạm dừng đổi cờ và nhãn; không tạo thêm interval mỗi lần bấm.',
[r(H,'function tuChuyenBanner(','Điều kiện tạm dừng'),r(H,'setInterval(tuChuyenBanner, 6000);','Chu kỳ gọi'),r(H,'function batTatTuChuyen(','Nút tạm dừng')],
'Đưa chuột ra ngoài và focus ô tìm kiếm để quan sát tự chuyển; sau đó focus vào banner để chứng minh dừng.',
'6 giây có chính xác tuyệt đối không? Không; lịch timer còn phụ thuộc trình duyệt và trạng thái tab.',
'Không kết luận slider hỏng khi focus vẫn nằm trên nút điều khiển.')
q('B13','Countdown và thời hạn cố định','Sao F5 không làm khuyến mãi bắt đầu đếm lại?',
'Hạn kết thúc được lưu cố định trong cấu hình, không được tạo bằng giờ mở trang cộng thêm thời gian. Mỗi lần cập nhật, em lấy hạn trừ Date.now rồi đổi ra ngày, giờ, phút và giây. Khi về 0, đồng hồ hiện đã kết thúc và dừng interval.',
'endsAt có múi giờ +07:00 → đổi thành mốc thời gian → trừ giờ hiện tại → chặn số âm → hiển thị. Trở lại tab cũng cập nhật theo giờ thực tế.',
[r(D,'"endsAt":','Thời hạn cấu hình'),r(H,'function capNhatDemNguoc(','Tính thời gian còn lại')],
'Quan sát countdown, chờ vài giây rồi F5. Khi luyện hết hạn dùng bản sao C05, không sửa đồng hồ hệ điều hành.',
'Hết hạn có tự gia hạn không? Không; muốn chiến dịch mới phải sửa cấu hình có chủ đích.',
'Không chỉ trừ một biến số giây trong bộ nhớ rồi tưởng vẫn đúng sau tab ẩn.')
q('B14','Giá khi hết khuyến mãi','Countdown hết rồi giá trong giỏ có còn giảm không?',
'Giá hiện hành do Product.layGia quyết định dựa trên điều kiện khuyến mãi. Các trang và tổng giỏ dùng chung phương thức đó, nên không có một giá giảm riêng chỉ nằm trên giao diện. Sự kiện hết khuyến mãi yêu cầu các vùng liên quan hiển thị lại; khi đặt hàng còn kiểm tra giá thêm lần nữa.',
'Đúng chiến dịch + salePrice hợp lệ + chưa hết hạn → giá giảm; ngược lại giá thường. Đơn đã lưu giữ snapshot đơn giá lúc đặt, không tự đổi theo chiến dịch sau đó.',
[r(M,'dangGiamGia(thoiDiem) {','Điều kiện giá giảm'),r(M,'layGia(thoiDiem) {','Giá thống nhất'),r(U,'function theoDoiKhuyenMai(','Thông báo hết hạn')],
'Bài C05 đặt thời hạn gần, để sẵn giỏ và form, quan sát tổng đổi nhưng thông tin đang nhập còn nguyên; lần đặt đầu yêu cầu xác nhận lại.',
'Chỉ sửa chữ countdown có đổi giá không? Không; phải sửa thời hạn cấu hình mà cả logic giá đang sử dụng.',
'Không dùng tổng hiển thị cũ để tạo đơn khi giá đã đổi.')
q('B15','Nhóm sản phẩm và danh mục','Mới, hot, khuyến mãi có phải ba danh mục không?',
'Danh mục phân loại hàng như laptop hoặc màn hình. Nhóm mới, hot và khuyến mãi mô tả trạng thái hoặc cách giới thiệu sản phẩm, nên một sản phẩm có thể ở nhiều nhóm. Dự án có cả hai cách để đáp ứng yêu cầu và giúp khách tìm hàng.',
'category chọn loại hàng; isNew/isHot là cờ; nhóm sale dựa vào khuyến mãi đang hiệu lực. Trang chủ chỉ lấy một phần sản phẩm mỗi nhóm, trang danh sách cho xem tập đầy đủ.',
[r(U,'function dungNhom(','Xác định nhóm'),r(H,'function hienThiCacNhomSanPham(','Giới hạn thẻ trang chủ')],
'Chỉ một laptop vừa mới vừa khuyến mãi. Mở Xem tất cả của một nhóm để giải thích vì sao số thẻ nhiều hơn trang chủ.',
'Hết hạn thì nhóm sale còn sản phẩm không? Có thể rỗng vì được lọc theo giá khuyến mãi đang hiệu lực.',
'Không hiểu số thẻ đang thấy trên trang chủ là tổng số sản phẩm trong dữ liệu.')
q('B16','Dữ liệu lưu bị hỏng','Nếu người dùng xóa storage, sửa JSON sai hoặc để ID cũ thì sao?',
'Hàm đọc storage bắt lỗi truy cập và JSON không phân tích được, sau đó dùng dữ liệu dự phòng và báo lỗi khi phù hợp. Cart còn kiểm tra từng dòng: bỏ ID lạ, số lượng sai, hàng hết và giới hạn số lượng theo kho. Đọc được JSON không có nghĩa dữ liệu đã hợp lệ.',
'docJSON xử lý lớp chuỗi/lưu trữ → kiemTraGio xử lý lớp nghiệp vụ → mảng hợp lệ mới được đưa vào Cart. Dòng trùng được gộp có giới hạn.',
[r(S,'function docJSON(','Bắt lỗi JSON'),r(M,'kiemTraGio(duLieu) {','Làm sạch giỏ đã lưu')],
'Trên phiên thử, ghi một ID không tồn tại hoặc JSON hỏng vào khóa giỏ rồi F5; kiểm tra trang không dừng bằng lỗi chưa xử lý.',
'Dữ liệu sai có được sửa hết trong storage ngay không? Không nên khẳng định; hàm khởi tạo làm sạch bản dùng trong bộ nhớ, ghi lại theo thao tác sau.',
'Không dùng try/catch thay cho kiểm tra kiểu và giá trị nghiệp vụ.')
q('B17','Trình duyệt chặn lưu trữ','Thêm được giỏ trên màn hình nhưng F5 mất thì giải thích thế nào?',
'Có thể thao tác đã cập nhật bộ nhớ nhưng ghi LocalStorage bị chặn. Ứng dụng phải báo rõ chưa lưu được, không bảo đảm dữ liệu còn sau F5 trong tình huống đó. Em phân biệt thành công của thao tác với thành công của bước lưu, thay vì chỉ nhìn badge.',
'Cart đổi → hàm lưu trả kết quả → giao diện cảnh báo. Đăng ký và đặt hàng không được báo thành công khi chưa lưu tài khoản hoặc đơn.',
[r(S,'function luuJSON(','Kết quả ghi'),r(E,'function xuLyThemGio(','Thông báo lưu giỏ'),r(O,'if (!luuTru.luuJSON(luuTru.ORDER_KEY, donHang))','Lỗi lưu đơn')],
'Dùng ca kiểm thử storage bị chặn trên bản sao/phiên thử; đối chiếu thông báo với dữ liệu đã lưu. Không hứa F5 giữ dữ liệu khi trình duyệt từ chối.',
'Tắt server có gây mất LocalStorage không? Không phải cơ chế xóa của ứng dụng; cần kiểm tra origin và cài đặt trình duyệt.',
'Không biến cảnh báo chưa lưu thành thông báo “đã lưu thành công”.')
q('B18','Địa chỉ và trình duyệt khác nhau','Đổi localhost sang 127.0.0.1 hoặc đổi Chrome sang Edge sao không thấy tài khoản?',
'LocalStorage gắn với origin và hồ sơ trình duyệt. Khác giao thức, tên máy hoặc cổng có thể là vùng lưu khác; Chrome và Edge cũng không tự chia sẻ dữ liệu. Vì vậy khi demo em giữ cùng địa chỉ và cùng hồ sơ để kiểm tra tính lưu sau F5.',
'Kiểm tra URL trước → xem đúng origin trong Application → kiểm tra khóa tài khoản. Với file://, cách lưu phụ thuộc trình duyệt; ưu tiên HTTP local cho buổi bảo vệ.',
[r(S,'chuoiJSON = window.localStorage.getItem(khoa);','Đọc storage của trang hiện tại'),r(D,"window.location.protocol === 'file:'",'Phân nhánh chế độ mở')],
'Ghi lại địa chỉ demo đang dùng; mở DevTools đúng tab. Không sửa code đăng nhập chỉ vì đang xem nhầm origin.',
'Copy thư mục sang máy khác có mang tài khoản đi không? Không; tài khoản nằm trong trình duyệt, không nằm trong JSON của website.',
'Không khẳng định storage của file:// giống hệt mọi origin HTTP trên mọi máy.')
q('B19','Giỏ giữa hai tab','Một tab thêm hàng thì tab giỏ biết thế nào?',
'Trang nghe sự kiện storage khi tab khác thay đổi LocalStorage cùng vùng lưu. Khi khóa giỏ thay đổi, nó đọc lại, kiểm tra và phát cart-changed để cập nhật giao diện. Trong chính tab thực hiện thao tác, mã tự phát sự kiện nội bộ sau khi lưu.',
'Tab A ghi → tab B nhận storage → đọc Cart mới → render. Sự kiện nội bộ và storage có vai trò khác nhau; không coi storage tự bắn lại trong chính tab ghi.',
[r(E,'function xuLyLuuTruThayDoi(','Nhận thay đổi tab khác'),r(E,'function luuGio(','Thông báo trong tab hiện tại')],
'Mở hai tab cùng địa chỉ, một tab giỏ một tab chi tiết. Thêm ở chi tiết rồi quan sát giỏ và badge.',
'Có chống xung đột nhiều người dùng như server không? Không; đây là đồng bộ trình duyệt đơn giản, không có giao dịch kho hay khóa ghi phân tán.',
'Không mô tả sự kiện storage là hệ thống đồng bộ tài khoản giữa các máy.')
q('B20','Giữ focus và tránh lặp render','Vì sao không xóa hết HTML giỏ rồi dựng lại mỗi lần đổi số lượng?',
'Dựng lại cả vùng có thể thay input đang focus và gây thêm blur/change không mong muốn. Em giữ các dòng còn tồn tại, cập nhật nội dung và chỉ thêm hoặc xóa dòng cần thiết. Cờ dangHienThi giúp tránh xử lý chồng khi đang hiển thị.',
'Tính dữ liệu → xóa dòng không còn → tìm dòng theo ID → tạo nếu thiếu → cập nhật input, giá, nút. finally trả cờ về false kể cả khi có lỗi trong quá trình hiển thị.',
[r(G,'function hienThiGioHang(','Render có kiểm soát'),r(G,'function capNhatDongGio(','Cập nhật dòng'),r(G,'function xuLyDoiSoLuong(','Kiểm tra cờ hiển thị')],
'Focus ô số lượng rồi thay giá trị hợp lệ; kiểm tra vẫn thao tác được và không tăng lặp. Thử nhập sai rồi Tab ra.',
'Có phải tuyệt đối không dùng innerHTML không? Không; tùy vùng. Form/giỏ cần giữ trạng thái nên không thay cả vùng tùy tiện.',
'Không sửa riêng text tổng tiền mà bỏ qua dữ liệu Cart.')
q('B21','Kiểm tra đăng ký','Tên đăng nhập và mật khẩu có những điều kiện nào?',
'Username sau trim dài 3–24 ký tự, gồm chữ không dấu, số, chấm, gạch dưới hoặc gạch ngang. Mật khẩu dài 8–64 ký tự, không toàn khoảng trắng và nhập lại phải khớp. Username được đưa về chữ thường để kiểm tra trùng; mật khẩu không tự đổi hoa thường hoặc trim trước khi băm.',
'Validate → chuẩn hóa username → tìm trùng → băm → đọc lại danh sách và kiểm tra trùng sau await → lưu. Đọc lại giúp không dùng danh sách cũ sau thời gian chờ.',
[r(S,'function kiemTraDangKy(','Quy tắc form'),r(S,'async function dangKy(','Kiểm tra tên trùng')],
'Thử tên ngắn, có dấu, mật khẩu ngắn và nhập lại khác. Sau khi đăng ký onthi01, thử ONTHI01 để kiểm tra trùng.',
'Hai tab ghi đồng thời có bảo đảm tuyệt đối không? Không có giao dịch như backend; không tuyên bố loại hết mọi tranh chấp đồng thời.',
'Không nói mật khẩu đang bắt buộc chữ hoa/số/ký tự đặc biệt nếu mã không kiểm tra điều đó.')
q('B22','Salt và mã băm','Salt là gì, cùng mật khẩu có ra cùng hash không?',
'Salt là chuỗi ngẫu nhiên riêng của lần đăng ký, được lưu cùng tài khoản. Dự án dùng Web Crypto với PBKDF2, SHA-256 và số vòng lặp cấu hình để tạo mã băm. Hai tài khoản dùng cùng mật khẩu nhưng salt khác thường có hash khác; khi đăng nhập phải dùng lại salt đã lưu.',
'Tạo 16 byte ngẫu nhiên → đổi hex để lưu → chuyển lại byte khi băm → dẫn xuất 256 bit → đổi hex. API trình duyệt thực hiện thuật toán, em không tự viết thuật toán mật mã.',
[r(S,'const SO_LAN_BAM =','Số vòng băm'),r(S,'async function bamMatKhau(','Web Crypto'),r(S,'const chuoiNgauNhien = doiSangHex','Tạo salt')],
'Đăng ký hai tài khoản thử cùng mật khẩu, xem salt và passwordHash khác nhau. Không đưa mật khẩu cá nhân vào ảnh minh chứng.',
'Salt có phải bí mật không? Không; nó được lưu cùng hash. Biết salt không đồng nghĩa lấy được mật khẩu trực tiếp.',
'Không gọi băm là mã hóa có khóa giải mã; không khẳng định hash làm frontend an toàn tuyệt đối.')
q('B23','Lý do giữ async await','Muốn mã cơ bản hơn thì bỏ async await được không?',
'Ở chỗ đọc JSON và băm mật khẩu, kết quả chưa có ngay nên cần chờ. async/await giúp diễn đạt thứ tự xử lý dễ đọc hơn việc cố dùng kết quả chưa hoàn tất. Em chỉ giữ nó tại các thao tác bất đồng bộ cần thiết, không thêm vào mọi hàm.',
'Gọi thao tác → nhận Promise → await chờ kết quả → kiểm tra lại điều kiện có thể thay đổi → tiếp tục. try/catch ở tầng gọi xử lý lỗi khi Promise bị từ chối.',
[r(D,'async function napDuLieuSanPham(','Chờ dữ liệu'),r(S,'const maBam = await bamMatKhau','Chờ băm'),r(A,'async function xuLyDangKy(','Bắt lỗi đăng ký')],
'Chỉ kết quả maBam chỉ được đưa vào danh sách sau await. Giải thích vì sao không thay bằng setTimeout đoán thời gian.',
'await có đóng băng toàn bộ trang không? Không; hàm tạm chờ, các sự kiện khác vẫn có thể xảy ra.',
'Không bỏ await chỉ để giảm dòng rồi lưu Promise thay cho hash.')
q('B24','Reset trong lúc đang băm','Đang đăng ký mà bấm kết thúc demo ở tab khác thì sao?',
'Trước khi bắt đầu, hàm ghi nhận mốc reset. Sau khi await băm xong, nó đọc lại mốc và so sánh; nếu thay đổi thì dừng, không ghi tài khoản hoặc phiên đăng nhập. Nhờ vậy kết quả xử lý cũ không phục hồi dữ liệu vừa bị xóa.',
'Đọc mốc → await → đọc lại mốc → khác thì trả lỗi → chỉ cùng mốc mới tiếp tục. Đăng nhập còn kiểm tra tài khoản hiện tại chưa bị thay.',
[r(S,'async function dangKy(','Mốc trước và sau chờ'),r(S,'async function dangNhap(','Kiểm tra lại phiên'),r(S,'function ketThucDemo(','Đổi mốc reset')],
'Xem ca hồi quy reset khi đang xử lý; khi luyện có thể dùng hai tab hoặc test làm chậm băm. Không cần sửa thuật toán mật khẩu của website.',
'Vì sao kiểm tra trước await chưa đủ? Trong thời gian chờ, người dùng hoặc tab khác có thể kết thúc demo.',
'Không báo đăng ký thành công nếu kết quả thuộc buổi demo cũ.')
q('B25','Giới hạn đăng nhập frontend','Nếu sửa LocalStorage bằng DevTools thì có giả đăng nhập được không?',
'Đây là tài khoản mô phỏng nên dữ liệu phía trình duyệt có thể bị người sử dụng sửa. Băm giúp không lưu mật khẩu nguyên văn, nhưng không tạo ra máy chủ tin cậy để kiểm tra quyền. Nếu làm hệ thống thật, cần backend xác thực, phân quyền và xử lý đơn/giá ở phía server.',
'Phân biệt lưu mật khẩu có băm với xác thực đáng tin cậy. Trong dự án, AUTH_KEY chỉ chứa username và được đối chiếu với danh sách tài khoản local, không phải token được server xác nhận.',
[r(S,'function layTaiKhoanDangNhap(','Đọc trạng thái local'),r(S,'if (!luuTru.luuJSON(luuTru.AUTH_KEY, { username:','Nội dung trạng thái đăng nhập')],
'Chỉ mã đọc tài khoản và nói rõ giới hạn. Không cần trình diễn sửa dữ liệu để giả quyền trong phiên demo chính.',
'Dùng để bảo vệ trang quản trị thật được chưa? Chưa; hiện dự án cũng không có chức năng quản trị.',
'Không nói PBKDF2 biến LocalStorage thành cơ sở dữ liệu bí mật hoặc chống sửa.')
q('B26','Bản nháp form và validation','Đang nhập email sai rồi F5 có mất form không?',
'Bản nháp lưu nguyên năm trường đang nhập, kể cả email chưa hoàn chỉnh. Khi mở lại, em chỉ khôi phục các giá trị có kiểu chuỗi hợp lệ; kiểm tra nghiệp vụ diễn ra khi gửi form. Như vậy người dùng không bị mất nội dung chỉ vì chưa nhập xong.',
'Sự kiện input tại form → đọc name/email/phone/address/note → lưu DRAFT_KEY. F5 đọc nháp → điền form; gửi thì trim/chuẩn hóa và hiển thị lỗi cạnh trường.',
[r(O,'function luuBanNhap(','Lưu khi input'),r(O,'function khoiPhucBanNhap(','Khôi phục từng chuỗi'),r(U,'function kiemTraKhachHang(','Kiểm tra khi gửi')],
'Nhập đủ năm trường với email còn thiếu, F5 kiểm tra còn nguyên; gửi để thấy lỗi và focus vào trường đầu sai.',
'Có lưu nháp mật khẩu không? Không; bản nháp này chỉ thuộc form đặt hàng.',
'Không chỉ lưu khi submit vì dữ liệu đang gõ sẽ mất trước lần gửi đầu.')
q('B27','Giá hoặc giỏ thay đổi','Giá đổi khi form đang mở, timer đã cập nhật tổng rồi thì có cần xác nhận nữa không?',
'Có. Trang giữ các dòng đã hiển thị và cờ cần xác nhận lại khi nội dung thay đổi. Khi gửi, nó so cả ID, số lượng và đơn giá, không chỉ so tổng tiền. Lần bấm phát hiện thay đổi chỉ nhắc xem lại và giữ form; lần xác nhận sau mới được tạo đơn nếu dữ liệu ổn định.',
'Cập nhật tóm tắt phát hiện khác → bật canXacNhanLai → submit kiểm tra cờ cùng snapshot → thông báo và return. Hai giỏ cùng tổng nhưng khác sản phẩm vẫn được nhận ra.',
[r(O,'function cacDongGiongNhau(','So từng dòng'),r(O,'function hienThiTongTien(','Ghi nhận thay đổi'),r(O,'if (canXacNhanLai ||','Yêu cầu xác nhận lại')],
'Mở form, đổi giỏ từ tab khác rồi quay lại bấm đặt; kiểm tra chưa có đơn ở lần cảnh báo và nội dung form còn nguyên.',
'Chỉ so total có đủ không? Không; đổi sang sản phẩm cùng giá sẽ không làm total đổi.',
'Không coi việc timer đã vẽ giá mới là bằng chứng khách đã xác nhận.')
q('B28','Lưu đơn lỗi và dọn giỏ lỗi','Lỗi trước hoặc sau khi lưu đơn xử lý có giống nhau không?',
'Không. Nếu lưu đơn thất bại, chưa có xác nhận thành công nên giữ form và giỏ để thử gửi lại. Nếu đơn đã lưu nhưng dọn giỏ lỗi, phải hiển thị đúng đơn đó và chỉ cho thử dọn lại. Cờ choDonGio giúp nhận biết bước còn dang dở sau F5.',
'Đơn lưu được → gắn mã xác nhận → thử dọn đúng giỏ khớp đơn. Khi thử lại, đọc đơn gần nhất và giỏ đã lưu; nếu giỏ đã đổi thì không tự xóa lựa chọn mới.',
[r(O,'if (!luuTru.luuJSON(luuTru.ORDER_KEY, donHang))','Lưu đơn thất bại'),r(O,'function thuDonGio(','Thử dọn đúng bước'),r(M,'xoaGio() {','Khôi phục bộ nhớ khi ghi giỏ lỗi')],
'Dùng bằng chứng ca hồi quy hoặc phiên test chặn ghi từng khóa; quan sát nút thử lại và mã đơn không đổi.',
'Giỏ mới trùng sản phẩm đơn cũ thì tự xóa không? Phải kiểm tra cả trạng thái đơn đã dọn ở storage, không chỉ so dòng.',
'Không tạo thêm đơn để giải quyết lỗi dọn giỏ.')
q('B29','Gửi lặp và F5 xác nhận','Bấm nhanh hai lần hoặc F5 trang xác nhận có sinh thêm đơn không?',
'Hàm submit kiểm tra trạng thái đang gửi và đơn đã xác nhận trước khi xử lý. Sau khi lưu, URL mang mã đơn và trang xác nhận đọc lại đơn đã lưu, không chạy submit. Vì vậy F5 xác nhận là đọc dữ liệu, không tạo đơn mới trong luồng đã kiểm thử.',
'Submit hợp lệ → khóa nút và trạng thái → lưu một snapshot → đổi URL. Khi khởi tạo, docDonDaDat kiểm tra cấu trúc đơn và mã trên URL để hiển thị lại.',
[r(O,'function xuLyDatHang(','Chặn gửi lặp'),r(O,'function docDonDaDat(','Đọc đơn theo URL'),r(O,'function donHangHopLe(','Kiểm tra snapshot')],
'Đặt hợp lệ, ghi mã đơn, bấm nhanh/Enter rồi F5; kiểm tra mã và tổng giữ nguyên. Xem ORDER_KEY chỉ có đơn gần nhất.',
'Đây có phải lịch sử mọi đơn không? Không; chỉ lưu đơn gần nhất của trình duyệt này.',
'Không tuyên bố có cơ chế idempotency đa người dùng như hệ thống backend.')
q('B30','Mở trực tiếp và Live Server','Vì sao mở HTML từng bị Failed to fetch, nay chạy được thế nào?',
'Khi mở file://, trình duyệt không cho đọc JSON bằng fetch như một trang HTTP thông thường. Dự án nạp chuỗi JSON dự phòng trong script rồi JSON.parse ở chế độ file; qua HTTP vẫn fetch products.json gốc. Bản dự phòng được sinh từ JSON nguồn, không phải bộ dữ liệu nhập tay khác.',
'Kiểm tra protocol → file thì parse chuỗi nhúng, HTTP thì fetch → cùng kiểm tra sản phẩm → cùng tạo Product. Cập nhật JSON rồi đóng gói sẽ đồng bộ bản dự phòng.',
[r(D,'async function napDuLieuSanPham(','Phân nhánh nạp dữ liệu'),r('js/san-pham-du-phong.js','window.PCAstral.offlineProductJSON =','JSON nhúng')],
'Giải nén toàn bộ thư mục, mở qua HTTP và nhấp đúp index.html. Không mở một file HTML bị tách khỏi js/img.',
'Nên dùng cách nào khi thi? Ưu tiên Live Server đúng thư mục; file:// là phương án dự phòng đã thử, hành vi storage/crypto vẫn tùy trình duyệt.',
'Không hướng dẫn tắt bảo mật trình duyệt để né lỗi fetch.')
